for(var elements=document.getElementsByClassName("donate-kgp-form"),i=0;i<elements.length;i++)create_sws_form_html(elements[i],i);function create_sws_form_html(n,z){var f='<form target="_blank" action="https://wsparcie.klubygp.pl/" method="GET" class="kgp-donation-form"><div class="kgp-header"><img style="height: 100px; max-height: 100px; margin-bottom: 20px;" src="data:image/png;base64," /><br /><strong>Wesprzyj budowanie&nbsp;społeczeństwa obywatelskiego</strong></div><div class="kgp-price-selector"><button class="kgp-btn kgp-select-'+z+'" id="kgp-btn-20-'+z+'" type="button" onclick="sws_change('+z+', 20)">20 zł</button><button class="kgp-btn kgp-select-'+z+'" id="kgp-btn-50-'+z+'" type="button" onclick="sws_change('+z+', 50)">50 zł</button><button class="kgp-btn kgp-select-'+z+'" id="kgp-btn-100-'+z+'" type="button" onclick="sws_change('+z+', 100)">100 zł</button><button class="kgp-btn kgp-select-'+z+'" id="kgp-btn-200-'+z+'" type="button" onclick="sws_change('+z+', 200)">200 zł</button><button class="kgp-btn kgp-select-'+z+'" id="kgp-btn-500-'+z+'" type="button" onclick="sws_change('+z+', 500)">500 zł</button><button class="kgp-btn kgp-select-'+z+'" id="kgp-btn-0-'+z+'" type="button" onclick="sws_change('+z+', 0)">inna</button></div><div class="kgp-custom-amount"><div style="display: none;" id="kgp-custom-container-'+z+'"><input id="kgp-amount-'+z+'" class="kgp-custom-amount-input" type="number" min="1" max="999999" name="amount" /> zł</div></div><button type="submit" class="kgp-btn-submit">Wspieram</button></form>';n.innerHTML=f+'<style>.kgp-header { color: #cb0b14; font-size: 18px; margin-bottom: 20px; text-transform: uppercase; } .kgp-donation-form { margin-top: 10px; margin-bottom: 10px; font-family: "Arial", "Helvetica", sans-serif; padding: 20px; border-radius: 5px; background: #f6f6f6; border: 1px solid silver; } .kgp-donation-form button { margin-bottom: 5px; margin-left: 2.5px; margin-right: 2.5px; min-width: 73px; font-size: 16px;} .selected { border: 2px solid #cb0b14 !important; color: #cb0b14 !important; font-weight: bold; } .kgp-btn { color: #000; background: white; padding: 10px; border: 1px solid silver; border-radius: 5px; cursor: pointer; } .kgp-btn:hover { border-color: #cb0b14; } .kgp-btn-submit { background: #cb0b14; color: white; padding: 10px; border: 0px; border-radius: 5px; cursor: pointer; margin-top: 10px; } .kgp-btn-submit:hover { background: #cb0b14; } .kgp-custom-amount-input { padding: 10px; font-size: 16px; border: 1px solid silver; border-radius: 5px; margin-top: 10px; margin-bottom: 10px; } .kgp-donation-form { width: auto; text-align: center; }</style>'}function sws_change(n,z){for(var f=document.getElementsByClassName("kgp-select-"+n),e=0;e<f.length;e++)sws_removeClass(f[e],"selected");sws_addClass(document.getElementById("kgp-btn-"+z+"-"+n),"selected"),z>0?(document.getElementById("kgp-amount-"+n).value=z,document.getElementById("kgp-custom-container-"+n).style.display="none"):(document.getElementById("kgp-amount-"+n).value="",document.getElementById("kgp-custom-container-"+n).style.display="block")}function sws_addClass(n,z){n.classList?n.classList.add(z):sws_hasClass(n,z)||(n.className+=" "+z)}function sws_removeClass(n,z){n.classList?n.classList.remove(z):n.className=n.className.replace(new RegExp("\\b"+z+"\\b","g"),"")}function sws_hasClass(n,z){return n.classList?n.classList.contains(z):new RegExp("\\b"+z+"\\b").test(n.className)}
